CREATE DATABASE IF NOT EXISTS kalamdesk; USE kalamdesk;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),email VARCHAR(150) UNIQUE,password_hash VARCHAR(255),role ENUM('owner','staff') DEFAULT 'staff');
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200) NOT NULL,category VARCHAR(60) DEFAULT 'Stationery',sku VARCHAR(60),price DECIMAL(10,2) NOT NULL,gst_pct DECIMAL(4,1) DEFAULT 0,stock INT DEFAULT 0,min_stock INT DEFAULT 5,active TINYINT DEFAULT 1);
CREATE TABLE book_sets(id INT AUTO_INCREMENT PRIMARY KEY,standard VARCHAR(40) NOT NULL,school VARCHAR(120) DEFAULT '',UNIQUE(standard,school));
CREATE TABLE set_items(set_id INT,product_id INT,qty INT DEFAULT 1,PRIMARY KEY(set_id,product_id),FOREIGN KEY(set_id) REFERENCES book_sets(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE invoices(id INT AUTO_INCREMENT PRIMARY KEY,customer_name VARCHAR(120),phone VARCHAR(20),email VARCHAR(150),discount DECIMAL(10,2) DEFAULT 0,total DECIMAL(10,2),created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoice_items(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT,product_id INT,name VARCHAR(200),qty INT,price DECIMAL(10,2),gst_pct DECIMAL(4,1),FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE);
